package server

// Seeding of the imported CyberStrikeAI tool recipes (P0.1).
//
// csitoolseeds.json is generated by artex-port/tools-import/convert_tools.py from
// CyberStrikeAI's tools/*.yaml (Apache-2.0). Every entry becomes one tools-table
// row: system=false, kind=command, enabled=true, deferred=true, agents=[] —
// dormant until the user binds it to an agent in the tool page, with the schema
// withheld until the model searches for it (SearchExtraTools/ExecuteExtraTool).
// SeedCustomTool is ON CONFLICT DO NOTHING, so user edits survive restarts.

import (
	_ "embed"
	"encoding/json"
	"log"

	"github.com/Autumn-27/artex/db"
)

//go:embed csitoolseeds.json
var csiToolSeedsJSON []byte

type csiToolSeed struct {
	Key         string          `json:"key"`
	Description string          `json:"description"`
	Schema      json.RawMessage `json:"schema"`
	Exec        json.RawMessage `json:"exec"`
}

func seedCSITools(pg *db.DB) {
	var doc struct {
		Tools []csiToolSeed `json:"tools"`
	}
	if err := json.Unmarshal(csiToolSeedsJSON, &doc); err != nil {
		log.Printf("[tools] CSI 配方解析失败: %v", err)
		return
	}
	added, total := 0, len(doc.Tools)
	for _, t := range doc.Tools {
		if t.Key == "" || len(t.Exec) == 0 {
			log.Printf("[tools] CSI 配方跳过空条目: %q", t.Key)
			continue
		}
		if err := pg.SeedCustomTool(&db.Tool{
			Key:         t.Key,
			Description: t.Description,
			Schema:      t.Schema,
			Agents:      []string{},
			Enabled:     true,
			Kind:        "command",
			Exec:        t.Exec,
			Deferred:    true,
		}); err != nil {
			log.Printf("[tools] CSI 配方 %s 播种失败: %v", t.Key, err)
			continue
		}
		added++
	}
	log.Printf("[tools] CSI 工具配方已播种 %d/%d 条（首插生效，已存在的行不动）", added, total)
}
